function Reports({requester,refresh,notify}){
 const [from,setFrom]=useState(daysAgo(14)),[to,setTo]=useState(dayToday()),[workerId,setWorkerId]=useState(''),[siteId,setSiteId]=useState('');
 const [busy,setBusy]=useState(''),[pdf,setPdf]=useState(null);
 const keys=['/admin/workers','/sites',`/admin/report?from=${from}&to=${to}${workerId?'&worker_id='+encodeURIComponent(workerId):''}${siteId?'&site_id='+encodeURIComponent(siteId):''}`];
 const {data,loading}=useRecords(requester,keys,refresh);
 const workers=data?.[0]?.workers||[],sites=data?.[1]?.sites||[],rows=data?.[2]?.rows||[];
 const total=rows.reduce((n,r)=>n+r.minutes,0);
 useEffect(()=>()=>{if(pdf?.url)URL.revokeObjectURL(pdf.url);},[pdf?.url]);
 const generate=async(format,print=false)=>{
  if(busy)return;
  if(!workerId){notify('Selecione primeiro um funcionário para gerar o relatório individual.');return;}
  setBusy(print?'print':format);
  try{
   const report=await fetchIndividualReport({from,to,workerId,siteId,format});
   if(print){
    if(window.ObraPontoAndroid?.printPdf){
     const dataUrl=await blobDataUrl(report.blob);
     window.ObraPontoAndroid.printPdf(dataUrl,report.name);
     notify('Selecione uma impressora ou Salvar como PDF.');
    }else if(window.ObraPontoAndroid){
     await saveReportFile(report);
     notify('PDF pronto. Para impressão direta, atualize o aplicativo Empresa para a versão 1.1.1.');
    }else{
     setPdf({...report,url:URL.createObjectURL(report.blob)});
    }
   }else{
    await saveReportFile(report);
    notify(window.ObraPontoAndroid?'Escolha onde salvar o arquivo.':'Download do arquivo solicitado.');
   }
  }catch(e){notify(e.message);}finally{setBusy('');}
 };
 return <>
 <SectionHead eyebrow="INTELIGÊNCIA OPERACIONAL" title="Relatórios de ponto"
 description="Escolha o funcionário e as datas. Gere um PDF para imprimir ou um Excel para editar."
 action={<div className="export-buttons">
  <Primary variant="btn-light" icon={Download} disabled={busy!==''||!rows.length} onClick={()=>{exportCsv(rows);notify('CSV exportado.');}}>CSV</Primary>
  <Primary icon={FileDown} disabled={busy!==''} onClick={()=>generate('pdf')}>{busy==='pdf'?'Gerando...':'Baixar PDF'}</Primary>
  <Primary icon={Printer} disabled={busy!==''} onClick={()=>generate('pdf',true)}>{busy==='print'?'Preparando...':'Visualizar / Imprimir'}</Primary>
  <Primary icon={FileSpreadsheet} disabled={busy!==''} onClick={()=>generate('xlsx')}>{busy==='xlsx'?'Gerando...':'Excel individual'}</Primary>
 </div>}/>
 <div className="filters-panel panel">
  <div className="filters-title"><SlidersHorizontal size={19}/><b>Filtros do relatório</b></div>
  <div className="filter-grid">
   <Field label="De"><TextInput type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field>
   <Field label="Até"><TextInput type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field>
   <Field label="Funcionário *"><Select value={workerId} onChange={e=>setWorkerId(e.target.value)}><option value="">Selecione para gerar PDF ou Excel</option>{workers.map(w=><option key={w.id} value={w.id}>{w.name}</option>)}</Select></Field>
   <Field label="Obra"><Select value={siteId} onChange={e=>setSiteId(e.target.value)}><option value="">Todas as obras</option>{sites.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</Select></Field>
  </div>
  {!workerId&&<p className="report-help"><Info size={16}/> Para gerar um relatório individual, selecione o funcionário acima.</p>}
 </div>
 <div className="report-stats"><div><span>Total de horas</span><strong>{fmtHours(total)}</strong></div><div><span>Dias com alocação / registro</span><strong>{rows.length}</strong></div><div><span>Profissionais no período</span><strong>{new Set(rows.map(r=>r.worker_id)).size}</strong></div></div>
 <div className="panel table-panel"><div className="panel-heading"><div><h3>Jornadas detalhadas</h3><p>Horas calculadas descontando os intervalos registrados</p></div><Pill text={`${rows.length} registros`}/></div>
 {loading&&!data?<Spinner/>:<div className="table-scroll"><table><thead><tr><th>DATA</th><th>FUNCIONÁRIO</th><th>OBRA / CIDADE</th><th>MARCAÇÕES</th><th>STATUS</th><th>HORAS</th></tr></thead><tbody>{rows.length?rows.map(r=><tr key={r.worker_id+r.day}><td>{shortDate(r.day)}</td><td><div className="two-line"><b>{r.worker_name}</b><small>{r.trade||'—'}</small></div></td><td><div className="two-line"><b>{r.site_name}</b><small>{r.site_city}</small></div></td><td className="punch-times">{r.punches.length?r.punches.map(p=><span title={labels[p.type]+(p.rectified?' (retificada)':'')} key={p.id}>{displayTime(p.at)}{p.rectified?' *':''}</span>):'—'}<RectificationDetails row={r}/></td><td>{statusPill(r.status)}</td><td className="metric-cell">{fmtHours(r.minutes)}</td></tr>):<tr><td colSpan="6"><Empty icon={ChartColumnIncreasing} title="Sem dados para o período" description="Altere os filtros ou aguarde novas marcações."/></td></tr>}</tbody></table></div>}</div>
 <p className="micro-note"><Info size={15}/> Os horários são mostrados no fuso de São Paulo. Relatórios operacionais não equivalem aos arquivos fiscais AFD/AEJ.</p>
 {pdf&&<PdfPrintPreview pdf={pdf} onClose={()=>setPdf(null)} notify={notify}/>}
 </>;
}

function RectificationDetails({row}){
 if(!row.rectified)return null;
 const actionNames={add:'Inclusão',adjust:'Ajuste',void:'Desconsideração'};
 return <details style={{marginTop:8,whiteSpace:'normal'}}><summary>Retificado — ver histórico</summary>
 <p><b>Originais:</b> {row.original_punches?.length?row.original_punches.map(p=>labels[p.type]+': '+displayTime(p.at)).join(' | '):'Sem marcação'}</p>
 {(row.rectifications||[]).map(c=><div key={c.id} style={{marginTop:8,overflowWrap:'anywhere'}}><b>{actionNames[c.action]} · {labels[c.type]}</b><div>{displayTime(c.previous_at)} → {displayTime(c.corrected_at)}</div><div>Motivo: {c.reason}</div><small>{c.actor_name} · {shortDate(c.created_at?.slice(0,10))} {displayTime(c.created_at)}</small></div>)}</details>;
}
function RectificationForm({item,requester,notify,onClose,onSaved}){
 const [data,setData]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const [action,setAction]=useState('adjust'),[target,setTarget]=useState(''),[type,setType]=useState('out'),[site,setSite]=useState(''),[time,setTime]=useState(''),[reason,setReason]=useState(''),[confirm,setConfirm]=useState(false);
 const endpoint='/admin/requests/'+encodeURIComponent(item.id)+'/rectification';
 useEffect(()=>{let alive=true;requester(endpoint).then(d=>{if(!alive)return;setData(d);setSite(d.site_id||'');if(!d.punches.length)setAction('add');}).catch(e=>{if(alive)setError(e.message);});return()=>{alive=false;};},[item.id]);
 const chooseTarget=id=>{setTarget(id);setTime(displayTime(data.punches.find(p=>p.id===id)?.at)==='—'?'':displayTime(data.punches.find(p=>p.id===id)?.at));setConfirm(false);};
 const submit=async e=>{e.preventDefault();if(busy||!data?.editable||!confirm)return;setBusy(true);setError('');try{await requester(endpoint,{method:'POST',body:{revision:data.revision,action,target_id:target,type,site_id:site,time,reason}});notify('Retificação registrada. Os pontos originais foram preservados.');onSaved();}catch(e){setError(e.message);setConfirm(false);}finally{setBusy(false);}};
 const close=()=>{if(!busy)onClose();};
 return <Modal title="Retificação de ponto" subtitle={item.worker_name+' · '+shortDate(item.day)} onClose={close}>
 {error&&<p role="alert" className="micro-note">{error}</p>}
 {!data&&!error&&<Spinner/>}
 {data&&<><p><b>Pedido:</b> {item.message}</p>
 <div className="panel" style={{padding:12,marginBottom:12}}><b>Marcações originais</b><p>{data.originals.length?data.originals.map(p=>labels[p.type]+': '+displayTime(p.at)).join(' | '):'Nenhuma marcação'}</p><b>Marcações consideradas</b><p>{data.punches.length?data.punches.map(p=>labels[p.type]+': '+displayTime(p.at)+(p.rectified?' (retificada)':'')).join(' | '):'Nenhuma marcação'}</p><RectificationDetails row={{rectified:data.rectifications.length>0,original_punches:data.originals,rectifications:data.rectifications}}/></div>
 {data.editable?<form className="stack-form" onSubmit={submit}>
 <Field label="Tipo de retificação"><Select value={action} onChange={e=>{setAction(e.target.value);setTarget('');setTime('');setConfirm(false);}}><option value="adjust" disabled={!data.punches.length}>Ajustar horário existente</option><option value="add">Incluir marcação esquecida</option><option value="void" disabled={!data.punches.length}>Desconsiderar marcação</option></Select></Field>
 {action==='add'?<><Field label="Marcação"><Select value={type} onChange={e=>{setType(e.target.value);setConfirm(false);}}>{Object.entries(labels).map(([v,l])=><option key={v} value={v}>{l}</option>)}</Select></Field><Field label="Obra"><Select required value={site} onChange={e=>{setSite(e.target.value);setConfirm(false);}}><option value="">Selecione a obra</option>{data.sites.map(s=><option key={s.id} value={s.id}>{s.name} — {s.city}</option>)}</Select></Field></>:<Field label="Marcação a retificar"><Select required value={target} onChange={e=>chooseTarget(e.target.value)}><option value="">Selecione a marcação</option>{data.punches.map(p=><option key={p.id} value={p.id}>{labels[p.type]} — {displayTime(p.at)}{p.rectified?' (retificada)':''}</option>)}</Select></Field>}
 {action!=='void'&&<Field label="Novo horário (São Paulo)"><TextInput type="time" required value={time} onChange={e=>{setTime(e.target.value);setConfirm(false);}}/></Field>}
 <Field label="Justificativa da administração"><textarea className="text-input text-area" required minLength={5} maxLength={500} value={reason} onChange={e=>{setReason(e.target.value);setConfirm(false);}} placeholder="Explique por que a marcação precisa ser retificada."/></Field>
 <p className="micro-note"><Info size={15}/> Esta ação altera somente o cálculo gerencial e mantém os registros originais e a auditoria.</p>
 <label className="setting-toggle"><input type="checkbox" checked={confirm} onChange={e=>setConfirm(e.target.checked)}/><span>Conferi os dados e confirmo a retificação.</span></label>
 <Primary type="submit" icon={Save} disabled={busy||!confirm||reason.trim().length<5||(action==='add'?!site:!target)||(action!=='void'&&!time)}>{busy?'Registrando...':'Confirmar retificação'}</Primary>
 </form>:<p className="micro-note"><Info size={15}/> Retificação indisponível para este pedido. É possível consultar o histórico.</p>}</>}
 </Modal>;
}
function AdminRequests({requester,refresh,notify}){
 const {data,loading}=useRecords(requester,['/admin/requests'],refresh);const items=data?.[0]?.requests||[];const [busy,setBusy]=useState(''),[editing,setEditing]=useState(null);
 const reload=()=>window.dispatchEvent(new Event('obraponto:refresh'));
 const decide=async(r,status)=>{setBusy(r.id);try{await requester('/admin/requests/'+r.id,{method:'PATCH',body:{status}});notify(status==='reviewed'?'Solicitação marcada como analisada.':'Solicitação recusada.');reload();}catch(e){notify(e.message);}finally{setBusy('');}};
 return <><SectionHead eyebrow="AJUSTES E JUSTIFICATIVAS" title="Solicitações" description="Acompanhe pedidos feitos pela equipe sem alterar as marcações originais."/><div className="panel"><div className="panel-heading"><div><h3>Pedidos dos funcionários</h3><p>Analise justificativas de esquecimento ou divergência no registro</p></div><Pill text={items.filter(r=>r.status==='pending').length+' pendentes'} tone="warning"/></div>{loading&&!data?<Spinner/>:<div className="requests-list">{items.length?items.map(r=><div className="request-row" key={r.id}><div className="request-avatar"><Avatar name={r.worker_name}/></div><div className="request-body"><div className="request-top"><b>{r.worker_name}</b><Pill text={r.rectified?'Retificada':r.status==='pending'?'Pendente':r.status==='reviewed'?'Analisada':'Recusada'} tone={r.rectified||r.status==='reviewed'?'success':r.status==='pending'?'warning':'danger'}/></div><div className="request-date"><CalendarDays size={14}/> Ponto de {shortDate(r.day)} • Enviada em {displayDateTime(r.created_at)}</div><p>{r.message}</p><div className="request-actions">{r.status==='pending'&&<><Primary variant="btn-sm" icon={CheckCircle2} disabled={busy===r.id} onClick={()=>decide(r,'reviewed')}>Marcar analisada</Primary><Primary variant="btn-sm btn-light" disabled={busy===r.id} onClick={()=>decide(r,'rejected')}>Recusar</Primary></>}{(r.rectified||(r.status!=='rejected'&&r.day<dayToday()))&&<Primary variant="btn-sm btn-light" icon={SquarePen} disabled={busy===r.id} onClick={()=>setEditing(r)}>{r.rectified?'Ver retificação':'Retificar ponto'}</Primary>}</div></div></div>):<Empty title="Nenhuma solicitação" description="Os pedidos de análise da equipe aparecerão aqui."/>}</div>}</div><p className="micro-note"><Info size={15}/> Marcar como analisada não corrige o horário. A retificação é uma ação separada, disponível para dias anteriores.</p>{editing&&<RectificationForm key={editing.id} item={editing} requester={requester} notify={notify} onClose={()=>setEditing(null)} onSaved={()=>{setEditing(null);reload();}}/>}</>;
}
function Worker({token,user,onLogout,refresh,notify}){
 const requester=useApi(token,onLogout);const [tab,setTab]=useState('home');const [online,setOnline]=useState(navigator.onLine);
 useEffect(()=>{const yes=()=>setOnline(true),no=()=>setOnline(false);window.addEventListener('online',yes);window.addEventListener('offline',no);return()=>{window.removeEventListener('online',yes);window.removeEventListener('offline',no);};},[]);
 const tabs=[['home',LayoutDashboard,'Início'],['history',CalendarDays,'Meu ponto'],['requests',ClipboardList,'Solicitações'],['profile',UserRound,'Perfil']];
 return <div className="worker-shell"><div className="worker-top"><Logo small/><div className="worker-top-right"><span className={`connection-mini ${online?'':'offline'}`}><span className="pulse-dot"/>{online?'Online':'Offline'}</span><Avatar name={user.name}/></div></div><main className="worker-content">{tab==='home'&&<WorkerHome requester={requester} refresh={refresh} user={user} notify={notify} online={online}/>} {tab==='history'&&<WorkerHistory requester={requester} refresh={refresh}/>} {tab==='requests'&&<WorkerRequests requester={requester} refresh={refresh} notify={notify}/>} {tab==='profile'&&<><WorkerProfile user={user} onLogout={onLogout}/><PrivacyPanel requester={requester} refresh={refresh} notify={notify}/></>}</main><div className="worker-tabbar">{tabs.map(([key,Icon,label])=><button key={key} onClick={()=>setTab(key)} className={tab===key?'active':''}><Icon size={21}/><span>{label}</span></button>)}</div></div>;
}
function LiveTime(){const [clock,setClock]=useState(new Date());useEffect(()=>{const i=setInterval(()=>setClock(new Date()),1000);return()=>clearInterval(i);},[]);return <div className="live-clock"><span>{new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(clock)}</span><small>Horário de Brasília</small></div>}
function WorkerHome({requester,refresh,user,notify,online}){
 const {data,loading}=useRecords(requester,['/worker/today','/sites'],refresh);const todayInfo=data?.[0],sites=data?.[1]?.sites?.filter(s=>s.active)||[];const [siteId,setSiteId]=useState(''),[busy,setBusy]=useState('');
 useEffect(()=>{if(todayInfo?.assignment?.site_id)setSiteId(todayInfo.assignment.site_id);else if(!siteId&&sites.length===1)setSiteId(sites[0].id);},[todayInfo?.assignment?.site_id,sites.map(s=>s.id).join('|')]);
 const chosenSite=sites.find(s=>s.id===siteId),punches=todayInfo?.punches||[],allowed=todayInfo?.allowed_types||['in'];const last=punches.at(-1);
 const status=last?.type==='out'?'Jornada encerrada':last?.type==='break_start'?'Em intervalo':last?'Em jornada':'Aguardando início';
 const punch=async(type)=>{if(!siteId){notify('Selecione o local de trabalho primeiro.');return;}setBusy(type);try{await requester('/worker/punch',{method:'POST',body:{type,site_id:siteId}});notify(`${labels[type]} registrada com sucesso às ${displayTime(new Date().toISOString())}.`);window.dispatchEvent(new Event('obraponto:refresh'));}catch(e){notify(e.message);}finally{setBusy('');}};
 const chooseSite=async(next)=>{setSiteId(next);if(!next)return;try{await requester('/worker/site',{method:'PUT',body:{site_id:next}});window.dispatchEvent(new Event('obraponto:refresh'));}catch(e){notify(e.message);}};
 return <><div className="worker-greeting"><div className="eyebrow">MEU PAINEL</div><h1>Olá, {user.name.split(' ')[0]}! <span>👋</span></h1><p>Pronto para mais um dia de trabalho?</p></div><div className="clock-card"><div className="clock-card-top"><span><Sun size={18}/> {displayDay(todayInfo?.day||dayToday())}</span><span className="realtime-chip"><CircleDot size={13}/> AO VIVO</span></div><LiveTime/><div className="clock-status"><span className={`status-dot ${last?.type==='in'||last?.type==='break_end'?'green':''}`}/>{status}</div></div>
 <div className="worker-panel worksite-panel"><div className="block-title"><span className="block-icon"><MapPinned size={20}/></span><div><h2>Meu local de trabalho</h2><small>Defina onde você está hoje</small></div></div>{loading&&!data?<Spinner/>:<><label className="field"><span>Obra / Local de hoje</span><Select value={siteId} onChange={e=>chooseSite(e.target.value)}><option value="">Selecione uma obra</option>{sites.map(s=><option key={s.id} value={s.id}>{s.name} — {s.city}</option>)}</Select></label>{chosenSite&&<div className="worksite-details"><MapPin size={16}/><span><strong>{chosenSite.name}</strong><small>{chosenSite.city}{chosenSite.address?', '+chosenSite.address:''}</small></span></div>}</>}</div>
 <div className="worker-panel punch-panel"><div className="block-title"><span className="block-icon lilac"><Clock3 size={20}/></span><div><h2>Registrar meu ponto</h2><small>Acompanhe sua jornada do dia</small></div></div><div className="punch-steps">{['in','break_start','break_end','out'].map((t,i)=>{const active=punches.some(p=>p.type===t),p=punches.find(p=>p.type===t);return <div className={`punch-step ${active?'done':''}`} key={t}><span className="step-circle">{active?<CheckCircle2 size={18}/>:i+1}</span><span><strong>{labels[t]}</strong><small>{p?displayTime(p.at):'—:—'}</small></span></div>;})}</div>{!online&&<div className="offline-msg"><WifiOff size={17}/> Conecte-se à internet para registrar seu ponto.</div>}{allowed.length===0?<div className="finished-msg"><CircleCheck size={22}/> Jornada finalizada. Bom descanso!</div>:<div className="punch-buttons">{allowed.includes('in')&&<Primary icon={DoorOpen} disabled={!siteId||!!busy||!online} onClick={()=>punch('in')}>{busy?'Registrando...':'Registrar entrada'}</Primary>}{allowed.includes('break_start')&&<Primary variant="btn-outline" icon={Coffee} disabled={!siteId||!!busy||!online} onClick={()=>punch('break_start')}>Iniciar intervalo</Primary>}{allowed.includes('break_end')&&<Primary icon={RefreshCcw} disabled={!siteId||!!busy||!online} onClick={()=>punch('break_end')}>Finalizar intervalo</Primary>}{allowed.includes('out')&&<Primary icon={DoorOpen} disabled={!siteId||!!busy||!online} onClick={()=>punch('out')}>Registrar saída</Primary>}</div>}<p className="punch-help"><ShieldCheck size={15}/> Horário confirmado pelo servidor. Cada marcação fica vinculada à obra selecionada.</p></div>
 {punches.length>0&&<div className="worker-panel"><div className="mini-title">Registros de hoje <Pill text={`${punches.length} marcações`} tone="blue"/></div><div className="worker-timeline">{punches.map(p=>{const Icon=IconEvent[p.type];return <div className="timeline-item" key={p.id}><span className="timeline-icon"><Icon size={16}/></span><div><b>{labels[p.type]}</b><small>{p.site_name}, {p.site_city}</small></div><strong>{displayTime(p.at)}</strong></div>})}</div></div>}</>;
}
function WorkerHistory({requester,refresh}){const [from,setFrom]=useState(daysAgo(30)),[to,setTo]=useState(dayToday());const {data,loading}=useRecords(requester,[`/worker/history?from=${from}&to=${to}`],refresh);const rows=data?.[0]?.rows||[];const total=rows.reduce((n,r)=>n+r.minutes,0);return <><div className="worker-greeting"><div className="eyebrow">MEUS REGISTROS</div><h1>Meu ponto</h1><p>Histórico das suas jornadas</p></div><div className="history-summary"><span><Clock3 size={19}/> Total do período</span><strong>{fmtHours(total)}</strong></div><div className="worker-panel"><div className="period-fields"><Field label="De"><TextInput type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Até"><TextInput type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field></div></div>{loading&&!data?<Spinner/>:<div className="history-list">{rows.length?rows.map(r=><div className="history-card" key={r.day}><div className="history-card-top"><div><span className="history-date">{shortDate(r.day)}</span><strong>{r.site_name}</strong><small><MapPin size={13}/>{r.site_city}</small></div>{statusPill(r.status)}</div><div className="history-card-bottom"><span><Clock3 size={16}/> {r.punches.length} marcações</span><strong>{fmtHours(r.minutes)}</strong></div><div className="history-punches">{r.punches.map(p=><span key={p.id} title={labels[p.type]+(p.rectified?' (retificada)':'')}>{displayTime(p.at)}{p.rectified?' *':''}</span>)}</div><RectificationDetails row={r}/></div>):<Empty title="Ainda sem registros" description="Seus pontos aparecerão aqui ao longo do mês."/>}</div>}</>}
function WorkerRequests({requester,refresh,notify}){const {data,loading}=useRecords(requester,['/worker/requests'],refresh);const requests=data?.[0]?.requests||[];const [day,setDay]=useState(dayToday()),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);const submit=async e=>{e.preventDefault();setBusy(true);try{await requester('/worker/requests',{method:'POST',body:{day,message}});setMessage('');notify('Solicitação enviada à administração.');window.dispatchEvent(new Event('obraponto:refresh'));}catch(e){notify(e.message);}finally{setBusy(false);}};return <><div className="worker-greeting"><div className="eyebrow">JUSTIFICATIVAS</div><h1>Solicitações</h1><p>Comunique erros ou esquecimentos no ponto</p></div><div className="worker-panel"><div className="block-title"><span className="block-icon lilac"><SquarePen size={20}/></span><div><h2>Solicitar análise</h2><small>Seu pedido será enviado ao administrador</small></div></div><form onSubmit={submit} className="stack-form"><Field label="Data do ponto"><TextInput type="date" required value={day} onChange={e=>setDay(e.target.value)}/></Field><Field label="O que aconteceu?"><textarea className="text-input text-area" required minLength={5} value={message} onChange={e=>setMessage(e.target.value)} placeholder="Ex.: Esqueci de registrar a saída às 17h..."/></Field><Primary type="submit" icon={Send} disabled={busy||!message.trim()}>{busy?'Enviando...':'Enviar solicitação'}</Primary></form></div><div className="worker-panel"><div className="mini-title">Minhas solicitações</div>{loading&&!data?<Spinner/>:<div className="my-requests">{requests.length?requests.map(r=><div className="my-request" key={r.id}><div className="request-top"><b>{shortDate(r.day)}</b><Pill text={r.rectified?'Retificada':r.status==='pending'?'Pendente':r.status==='reviewed'?'Analisada':'Recusada'} tone={r.rectified||r.status==='reviewed'?'success':r.status==='pending'?'warning':'danger'}/></div><p>{r.message}</p><small>Enviada em {displayDateTime(r.created_at)}</small></div>):<Empty title="Nenhum pedido enviado" description="Se precisar de ajuda com algum registro, envie uma solicitação acima."/>}</div>}</div></>}

function PrivacyPanel({requester,refresh,notify,admin=false}){
 const {data,loading}=useRecords(requester,admin?['/privacy/requests','/admin/privacy/requests']:['/privacy/requests'],refresh);
 const mine=data?.[0]?.requests||[],queue=data?.[1]?.requests||[];
 const [kind,setKind]=useState('access'),[message,setMessage]=useState(''),[busy,setBusy]=useState(false),[editing,setEditing]=useState(null),[response,setResponse]=useState('');
 const kinds={access:'Acesso aos meus dados',correction:'Correção de dados pessoais',deletion:'Exclusão da conta e dados elegíveis'};
 const states={pending:'Recebida',in_review:'Em análise',answered:'Respondida'};
 const reload=()=>window.dispatchEvent(new Event('obraponto:refresh'));
 const submit=async e=>{e.preventDefault();if(busy)return;setBusy(true);try{await requester('/privacy/requests',{method:'POST',body:{kind,message}});setMessage('');notify('Solicitação registrada.');reload();}catch(e){notify(e.message);}finally{setBusy(false);}};
 const decide=async(status)=>{if(busy||!editing)return;setBusy(true);try{await requester('/admin/privacy/requests/'+editing.id,{method:'PATCH',body:{status,response}});setEditing(null);setResponse('');notify('Atendimento registrado.');reload();}catch(e){notify(e.message);}finally{setBusy(false);}};
 return <div className={admin?'panel':'worker-panel'} style={{padding:16,marginTop:16}}><h3>Privacidade e dados pessoais</h3><p>Solicite acesso, correção ou exclusão dos seus dados. A exclusão será analisada e os registros sujeitos à retenção obrigatória serão preservados.</p>
 <form className="stack-form" onSubmit={submit}><Field label="Tipo de solicitação"><Select value={kind} onChange={e=>setKind(e.target.value)}>{Object.entries(kinds).map(([k,v])=><option key={k} value={k}>{v}</option>)}</Select></Field><Field label="Descreva seu pedido"><textarea className="text-input text-area" required minLength={5} maxLength={1000} value={message} onChange={e=>setMessage(e.target.value)}/></Field><Primary type="submit" disabled={busy||message.trim().length<5}>Enviar solicitação</Primary></form>
 <h4>Minhas solicitações</h4>{loading&&!data?<Spinner/>:mine.map(p=><div key={p.id} style={{padding:10,borderBottom:'1px solid #D8E1EA',overflowWrap:'anywhere'}}><b>{kinds[p.kind]}</b> · {states[p.status]}<p>{p.message}</p>{p.response&&<p><b>Resposta:</b> {p.response}</p>}</div>)}
 {admin&&<><h4>Solicitações recebidas</h4>{queue.map(p=><div key={p.id} style={{padding:10,borderBottom:'1px solid #D8E1EA',overflowWrap:'anywhere'}}><b>{p.user_name} · {kinds[p.kind]}</b> · {states[p.status]}<p>{p.message}</p>{p.response&&<p>{p.response}</p>}{p.status!=='answered'&&<Primary variant="btn-sm btn-light" disabled={busy} onClick={()=>{setEditing(p);setResponse(p.response||'');}}>Atender</Primary>}</div>)}</>}
 {editing&&<Modal title="Atender solicitação de privacidade" onClose={()=>{if(!busy)setEditing(null);}}><p>{editing.user_name} — {kinds[editing.kind]}</p><p>{editing.message}</p><Field label="Resposta e providências adotadas"><textarea className="text-input text-area" maxLength={2000} value={response} onChange={e=>setResponse(e.target.value)}/></Field><p className="micro-note">Responder não exclui automaticamente a conta ou os dados. Registre as providências efetivamente realizadas.</p><div className="request-actions"><Primary disabled={busy} onClick={()=>decide('in_review')}>Em análise</Primary><Primary disabled={busy||response.trim().length<10} onClick={()=>decide('answered')}>Registrar resposta</Primary></div></Modal>}
 </div>;
}

function WorkerProfile({user,onLogout}){const fields=[[UserRound,'Nome completo',user.name],[BriefcaseBusiness,'Função',user.trade||'Não informada'],[Hash,'Matrícula',user.employee_code||'Não informada'],[Mail,'E-mail',user.email],[Phone,'Telefone',user.phone||'Não informado']];return <><div className="worker-greeting"><div className="eyebrow">MINHA CONTA</div><h1>Meu perfil</h1><p>Dados cadastrados pela empresa</p></div><div className="worker-profile-card"><Avatar name={user.name} size="large"/><h2>{user.name}</h2><Pill text={user.trade||'Funcionário'} tone="blue"/></div><div className="worker-panel profile-fields">{fields.map(([Icon,title,value])=><div className="profile-row" key={title}><span className="profile-icon"><Icon size={18}/></span><div><small>{title}</small><strong>{value}</strong></div></div>)}</div><Primary variant="btn-light btn-block" icon={LogOut} onClick={onLogout}>Sair da conta</Primary></>}
function App(){const [token,setToken]=useState(localStorage.getItem(APP_KEY)||''),[user,setUser]=useState(null),[checking,setChecking]=useState(!!localStorage.getItem(APP_KEY)),[refresh,setRefresh]=useState(0),[toast,setToast]=useState('');
 const logout=()=>{localStorage.removeItem(APP_KEY);setToken('');setUser(null);};
 const onLogin=({token,user})=>{localStorage.setItem(APP_KEY,token);setToken(token);setUser(user);};
 useEffect(()=>{if(!token){setChecking(false);return;}let alive=true;setChecking(true);api('/me',{token}).then(d=>{if(alive){if(d.user.role!==(isAdminApp?'admin':'worker')){logout();return;}setUser(d.user);}}).catch(()=>{if(alive)logout();}).finally(()=>{if(alive)setChecking(false);});return()=>{alive=false;};},[token]);
 useEffect(()=>{if(!token)return;const s=io({auth:{token},transports:['websocket','polling'],reconnection:true});s.on('changed',()=>setRefresh(n=>n+1));const handler=()=>setRefresh(n=>n+1);window.addEventListener('obraponto:refresh',handler);return()=>{s.disconnect();window.removeEventListener('obraponto:refresh',handler);};},[token]);
 useEffect(()=>{const handler=e=>setToast(e.detail);window.addEventListener('obraponto:error',handler);return()=>window.removeEventListener('obraponto:error',handler);},[]);
 useEffect(()=>{if('serviceWorker'in navigator && import.meta.env.PROD){navigator.serviceWorker.register(isAdminApp?'/admin/sw.js':'/funcionario/sw.js',{scope:isAdminApp?'/admin/':'/funcionario/'}).catch(()=>{});}},[]);
 return <>{checking?<div className="app-loading"><Logo/><Spinner/></div>:(!token||!user)?<Login onLogin={onLogin}/>:isAdminApp?<Admin token={token} user={user} onLogout={logout} refresh={refresh} notify={setToast}/>:<Worker token={token} user={user} onLogout={logout} refresh={refresh} notify={setToast}/>}<Toast message={toast} clear={()=>setToast('')}/></>;
}

createRoot(document.getElementById('root')).render(<App/>);
